def _get(name: str) -> List[float]:
    for n, v in EXPECTED:
        if n == name:
            return v
    raise ValueError("missing " + name)

def check(name: str, got, rtol: float = 1e-7, atol: float = 1e-10):
    want = _get(name)
    g = List[float]()
    for v in got:
        if isinstance(v, np.ndarray):
            for w in v.ravel():
                g.append(float(w))
        else:
            g.append(float(v))
    ok = len(g) == len(want)
    if ok:
        for i in range(len(want)):
            if abs(g[i] - want[i]) > atol + rtol * abs(want[i]):
                ok = False
    if not ok:
        print("TEST FAILED:", name, g, want)

rng = np.random.RandomState(0)
X = np.vstack([rng.randn(25, 2) * 0.3 + np.array([0., 0.]), rng.randn(25, 2) * 0.5 + np.array([3., 3.]),
               rng.randn(25, 2) * 0.2 + np.array([0., 4.]), rng.uniform(-2, 5, (8, 2))])

o = OPTICS(min_samples=5).fit(X)
check("op_order", o.ordering_)
check("op_core", o.core_distances_, 1e-12, 1e-14)
check("op_reach", np.where(np.isinf(o.reachability_), -1., o.reachability_), 1e-12, 1e-14)
check("op_pred", o.predecessor_)
check("op_labels", o.labels_)
check("op_hier", [o.cluster_hierarchy_])
o2 = OPTICS(min_samples=4, xi=0.1, min_cluster_size=0.1, metric="manhattan").fit(X)
check("op2_labels", o2.labels_)
o3 = OPTICS(min_samples=6, cluster_method="dbscan", eps=0.6).fit(X)
check("op3_labels", o3.labels_)
check("op_dbscan_fn", cluster_optics_dbscan(reachability=o.reachability_, core_distances=o.core_distances_, ordering=o.ordering_, eps=0.4))

h = HDBSCAN(min_cluster_size=5, copy=False).fit(X)
check("hd_labels", h.labels_)
check("hd_probs", h.probabilities_, 1e-9, 1e-12)
h2 = HDBSCAN(min_cluster_size=6, min_samples=3, cluster_selection_method="leaf", copy=False).fit(X)
check("hd2_labels", h2.labels_)
check("hd2_probs", h2.probabilities_, 1e-9, 1e-12)
h3 = HDBSCAN(min_cluster_size=5, cluster_selection_epsilon=1.5, store_centers="both", copy=False).fit(X)
check("hd3_labels", h3.labels_)
check("hd3_centroids", [h3.centroids_], 1e-9, 1e-12)
check("hd3_medoids", [h3.medoids_], 1e-9, 1e-12)
check("hd_cut", h.dbscan_clustering(0.5, min_cluster_size=4))
